/* CSP hashes allow our two inline scripts but no arbitrary injected script. */
let mrxpCspPromise=null;
async function mrxpPageCsp(){
 if(!mrxpCspPromise)mrxpCspPromise=Promise.all(
  [...html.matchAll(/<script\b[^>]*>([\s\S]*?)<\/script>/gi)]
   .map(m=>m[1]).filter(Boolean).map(async script=>{
    const bytes=new Uint8Array(await crypto.subtle.digest("SHA-256",encoder.encode(script)));
    return "'sha256-"+btoa(String.fromCharCode(...bytes))+"'"
   })
 ).then(hashes=>`default-src 'self' https://telegram.org https://*.telegram.org; script-src 'self' https://telegram.org ${hashes.join(" ")}; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; connect-src 'self'; img-src 'self' data: blob: https://raw.githubusercontent.com https://t.me https://telegram.org https://*.telegram.org https://*.telegram-cdn.org; object-src 'none'; base-uri 'none'; frame-ancestors https://web.telegram.org https://*.telegram.org`);
 return mrxpCspPromise
}
const page=async()=>new Response(html,{headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-store, max-age=0, must-revalidate","content-security-policy":await mrxpPageCsp()}});
const hex=a=>Array.from(new Uint8Array(a)).map(b=>b.toString(16).padStart(2,"0")).join("");
async function hmac(key,content){const imported=await crypto.subtle.importKey("raw",typeof key==="string"?encoder.encode(key):key,{name:"HMAC",hash:"SHA-256"},false,["sign"]);return crypto.subtle.sign("HMAC",imported,encoder.encode(content))}
function equalSignature(expected,supplied){if(typeof supplied!=="string"||!(/^[0-9a-fA-F]{64}$/.test(supplied)))return false;let diff=0;for(let i=0;i<expected.length;i++)diff|=expected.charCodeAt(i)^supplied.toLowerCase().charCodeAt(i);return diff===0}
async function authenticate(req,env){
 const token=typeof env.BOT_TOKEN==="string"?env.BOT_TOKEN.trim():"";
 if(!token)return {reason:"TOKEN_ABSENT"};
 const raw=req.headers.get("x-telegram-init-data")||"";
 if(!raw)return {reason:"INITDATA_ABSENTE"};
 if(raw.length>8192)return {reason:"INITDATA_TROP_LONGUE"};
 const p=new URLSearchParams(raw),hash=p.get("hash"),ts=Number(p.get("auth_date"));
 if(!hash||!Number.isFinite(ts)||ts<=0)return {reason:"CHAMPS_MANQUANTS"};
 const age=Math.floor(Date.now()/1000)-ts;
 if(age>86400)return {reason:"SESSION_EXPIREE"};
 if(age < -300)return {reason:"HORLOGE_INVALIDE"};
 p.delete("hash");
 const pairs=[...p.entries()].sort((a,b)=>a[0].localeCompare(b[0]));
 const signingKey=await hmac("WebAppData",token);
 const variants=[pairs,pairs.filter(([key])=>key!=="signature")];
 let verified=false;
 for(const items of variants){const checkString=items.map(([k,v])=>k+"="+v).join("\n");const signature=hex(await hmac(signingKey,checkString));if(equalSignature(signature,hash)){verified=true;break}}
 if(!verified)return {reason:"SIGNATURE_INVALIDE"};
 try{const user=JSON.parse(p.get("user")||"null");if(!user||typeof user!=="object"||!user.id)return {reason:"UTILISATEUR_ABSENT"};return {user:{id:String(user.id),username:String(user.username||"").slice(0,64),name:([user.first_name,user.last_name].filter(v=>typeof v==="string"&&v.trim()).join(" ").trim()||String(user.username||"Joueur Telegram")).slice(0,90),photoUrl:typeof user.photo_url==="string"?user.photo_url.slice(0,1024):""}}}
 catch{return {reason:"UTILISATEUR_INVALIDE"}}
}
let healthTelegramCache={expires:0,valid:false,username:null};
const DAY=86400000,HALF=43200000;
const dateOf=ms=>new Date(ms).toISOString().slice(0,10);
const rewards=[["xp10",30,10],["xp25",22,25],["bonus",15,20],["xp50",8,50],["ticket",10,15],["xp100",7,100],["shield",5,30],["badge",3,75]];
async function wheelOutcome(env,id,day){const b=new Uint8Array(await hmac(env.BOT_TOKEN,"mrxp-play-wheel-v1:"+id+":"+day));let pick=((b[0]<<8)+b[1])%100;for(const r of rewards){if(pick<r[1])return {key:r[0],xp:r[2]};pick-=r[1]}return {key:"xp10",xp:10}}
async function ensurePlayer(env,u){const now=Date.now();await env.DB.prepare("INSERT OR IGNORE INTO players(user_id,username,display_name,next_sync_ms,created_ms,updated_ms) VALUES(?,?,?,?,?,?)").bind(u.id,u.username,u.name,now,now,now).run();await env.DB.prepare("UPDATE players SET username=?,display_name=?,updated_ms=? WHERE user_id=?").bind(u.username,u.name,now,u.id).run();return env.DB.prepare("SELECT * FROM players WHERE user_id=?").bind(u.id).first()}
function validDay(d,now){if(typeof d!=="string"||!/^\d{4}-\d{2}-\d{2}$/.test(d))return false;const ms=Date.parse(d+"T00:00:00Z");const todayMs=Math.floor(now/DAY)*DAY;return Number.isFinite(ms)&&ms<=todayMs&&ms>=todayMs-14*DAY;}


/* V2 Phase 1: levels are awarded from verified lifetime XP and audited mastery.
   Legacy users keep their pre-migration *confirmed* tap level as an immutable floor.
   Do not award XP for mastery itself: these are access conditions, not paid rewards. */
const V2_MAX_LEVEL=50;
const V2_LEVEL_THRESHOLDS=[0,0];
for(let l=1;l<V2_MAX_LEVEL;l++)V2_LEVEL_THRESHOLDS[l+1]=V2_LEVEL_THRESHOLDS[l]+Math.round(200+100*Math.pow(l,1.4));
const V2_RANKS=[
 {from:1,to:1,name:"Recrue"},{from:2,to:2,name:"Éclaireur"},{from:3,to:4,name:"Combattant"},
 {from:5,to:5,name:"Sentinelle"},{from:6,to:9,name:"Chevalier"},{from:10,to:14,name:"Élite"},
 {from:15,to:19,name:"Maître"},{from:20,to:29,name:"Champion"},
 {from:30,to:39,name:"Légende"},{from:40,to:49,name:"Mythique"},
 {from:50,to:50,name:"Souverain MX"}
];
const V2_GATES=[{level:5,required:2},{level:10,required:3},{level:15,required:5},
 {level:20,required:7},{level:30,required:10},{level:40,required:14},{level:50,required:18}];
const V2_MASTERY=[
 ...[50,200,500,1000,2500,5000,10000,20000,50000,100000,200000,400000].map(n=>({key:"taps_"+n,name:n.toLocaleString("fr-FR")+" tapotages",kind:"taps",goal:n})),
 ...[2,5,10,20,40,80,160].map(n=>({key:"daily_"+n,name:n+" bonus quotidiens",kind:"daily",goal:n})),
 ...[2,5,10,20,40,80,160].map(n=>({key:"wheel_"+n,name:n+" tours de roue",kind:"wheel",goal:n})),
 ...[1,2,3,4].map(n=>({key:"missions_"+n,name:n+" missions gratuites",kind:"missions",goal:n}))
];
function v2Rank(level){return V2_RANKS.find(r=>level>=r.from&&level<=r.to)||V2_RANKS[0]}
function v2XpLevel(xp){let n=1;while(n<V2_MAX_LEVEL&&xp>=V2_LEVEL_THRESHOLDS[n+1])n++;return n}
function v2LegacyLevel(taps){return Math.min(V2_MAX_LEVEL,Math.max(1,Math.floor(Math.sqrt(Math.max(0,Number(taps)||0)/250))+1))}
async function v2Progression(env,player){
 const id=String(player.user_id),now=Date.now(),xp=Math.max(0,Number(player.confirmed_xp)||0),taps=Math.max(0,Number(player.confirmed_taps)||0);
 let row=await env.DB.prepare("SELECT * FROM player_progress_v2 WHERE user_id=?").bind(id).first();
 if(!row){
  const floor=v2LegacyLevel(taps);
  await env.DB.prepare("INSERT OR IGNORE INTO player_progress_v2(user_id,legacy_level_floor,current_level,created_ms,updated_ms) VALUES(?,?,?,?,?)").bind(id,floor,floor,now,now).run();
  row=await env.DB.prepare("SELECT * FROM player_progress_v2 WHERE user_id=?").bind(id).first();
  if(!row)throw Error("Progression V2 indisponible");
 }
 const counted=await env.DB.prepare("SELECT (SELECT COUNT(*) FROM daily_claims WHERE user_id=?) AS daily_count,(SELECT COUNT(*) FROM wheel_claims WHERE user_id=?) AS wheel_count,(SELECT COUNT(*) FROM mission_claims WHERE user_id=? AND mission_key NOT IN ('join_main','join_foot')) AS mission_count").bind(id,id,id).first();
 const totals={taps,daily:Number(counted?.daily_count||0),wheel:Number(counted?.wheel_count||0),missions:Number(counted?.mission_count||0)};
 const challenges=V2_MASTERY.map(a=>({key:a.key,name:a.name,kind:a.kind,goal:a.goal,progress:Math.min(a.goal,totals[a.kind]),completed:totals[a.kind]>=a.goal}));
 const earned=challenges.filter(a=>a.completed).length;
 const xpEligible=v2XpLevel(xp),floor=Math.max(1,Math.min(V2_MAX_LEVEL,Number(row.legacy_level_floor)||1));
 let official=Math.max(floor,Math.min(V2_MAX_LEVEL,Number(row.current_level)||1));
 for(let next=official+1;next<=xpEligible;next++){
  const gate=V2_GATES.find(g=>g.level===next);
  if(gate&&earned<gate.required)break;
  official=next;
 }
 if(official>Number(row.current_level||1)){
  await env.DB.prepare("UPDATE player_progress_v2 SET current_level=MAX(current_level,?),updated_ms=? WHERE user_id=?").bind(official,now,id).run();
 }
 const nextLevel=Math.min(V2_MAX_LEVEL,official+1);
 const nextGate=V2_GATES.find(g=>g.level>official)||null;
 const stopped=V2_GATES.find(g=>g.level===nextLevel&&earned<g.required)||null;
 const lower=V2_LEVEL_THRESHOLDS[official]||0,upper=V2_LEVEL_THRESHOLDS[nextLevel]||lower;
 const progress=official>=V2_MAX_LEVEL?100:Math.round(100*Math.min(1,Math.max(0,(xp-lower)/Math.max(1,upper-lower))));
 const nextRank=V2_RANKS.find(r=>r.from>official)||null;
 const nextRankGate=nextRank?V2_GATES.find(g=>g.level===nextRank.from):null;
 const nextRankDetails=nextRank?{
   name:nextRank.name,level:nextRank.from,xp_required:V2_LEVEL_THRESHOLDS[nextRank.from],
   xp_remaining:Math.max(0,V2_LEVEL_THRESHOLDS[nextRank.from]-xp),
   mastery_required:nextRankGate?.required||0,mastery_completed:earned,
   mastery_missing:Math.max(0,(nextRankGate?.required||0)-earned)
 }:null;
 return {
  version:2,level:official,rank:v2Rank(official).name,max_level:V2_MAX_LEVEL,legacy_level_floor:floor,
  confirmed_xp:xp,xp_eligible_level:xpEligible,xp_current_threshold:lower,xp_next_threshold:official>=V2_MAX_LEVEL?null:upper,
  xp_to_next:official>=V2_MAX_LEVEL?0:Math.max(0,upper-xp),xp_progress_percent:progress,
  blocked_by_mastery:!!stopped,required_mastery:stopped?.required||0,
  mastery:{completed:earned,total:challenges.length,challenges,next_gate:nextGate?{level:nextGate.level,required:nextGate.required,missing:Math.max(0,nextGate.required-earned)}:null},
  next_rank:nextRankDetails,
  progress_pending:false
 };
}


/* Phase 2 — permanent, per-account choice of a cosmetic avatar.
   The rank badge always reflects the official server level. Selecting an older
   unlocked portrait does NOT change the level or any progression metrics. */
const V2_RANK_PORTRAITS=[
 "rank-01-recrue.webp","rank-02-eclaireur.webp","rank-03-combattant.webp",
 "rank-04-sentinelle.webp","rank-05-chevalier.webp","rank-06-elite.webp",
 "rank-07-maitre.webp","rank-08-champion.webp","rank-09-legende.webp",
 "rank-10-mythique.webp","rank-11-souverain-mx.webp"
];
function v2CurrentRankIndex(level){return Math.max(0,V2_RANKS.findIndex(r=>level>=r.from&&level<=r.to))}
async function v2PlayerProfile(env,player,progression){
 const userId=String(player.user_id),currentRank=v2CurrentRankIndex(progression.level)+1;
 const pref=await env.DB.prepare("SELECT selected_rank FROM player_avatar_prefs WHERE user_id=?").bind(userId).first();
 const saved=Number(pref?.selected_rank||0);
 const selectedRank=Number.isInteger(saved)&&saved>=1&&saved<=currentRank?saved:currentRank;
 const collection=V2_RANKS.map((r,index)=>({
   id:index+1,name:r.name,from:r.from,to:r.to,
   image:V2_RANK_PORTRAITS[index],unlocked:progression.level>=r.from,
   current:index+1===currentRank,selected:index+1===selectedRank
 }));
 return {level:progression.level,rank:progression.rank,
   current_rank_id:currentRank,selected_rank_id:selectedRank,
   selection_mode:saved>=1&&saved<=currentRank?"custom":"auto",
   avatar_image:V2_RANK_PORTRAITS[selectedRank-1],
   collection,unlocked_count:collection.filter(a=>a.unlocked).length,total_count:collection.length,
   cosmetics_only:true
 };
}


/* V2 Phase 3 — signed, expiring snapshots of server-confirmed public stats.
   Tokens reveal no Telegram numeric ID, private handle or unconfirmed XP.
   Verification is optional and expires automatically after 30 days. */
const MRXP_SHARE_TTL_MS=30*24*60*60*1000;
const MRXP_SHARE_IMAGE_ROOT="https://raw.githubusercontent.com/MrXPRONOS/MrXPRONOS_App/main/mrxpronos-play/assets/07-rank-avatars/";
function mrxpSafeName(str){return String(str||"").replace(/[<>&"'\u0000-\u001f\u007f]/g," ").replace(/\s+/g," ").trim().slice(0,42)||"Joueur MRXP"}
function mrxpBase64url(bytes){let binary="";for(const byte of bytes)binary+=String.fromCharCode(byte);return btoa(binary).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"")}
function mrxpUnbase64url(str){if(!/^[A-Za-z0-9_-]+$/.test(str)||str.length>4000)throw Error("INVALID_SHARE_TOKEN");const binary=atob(str.replace(/-/g,"+").replace(/_/g,"/"));return Uint8Array.from(binary,c=>c.charCodeAt(0))}
async function mrxpShareKey(env){if(!env.BOT_TOKEN)throw Error("Share signing unavailable");return crypto.subtle.importKey("raw",new TextEncoder().encode("mrxp-share-v1:"+env.BOT_TOKEN),{name:"HMAC",hash:"SHA-256"},false,["sign","verify"])}
async function mrxpShareToken(env,snapshot){
 const payload=mrxpBase64url(new TextEncoder().encode(JSON.stringify(snapshot)));
 const sig=await crypto.subtle.sign("HMAC",await mrxpShareKey(env),new TextEncoder().encode(payload));
 return payload+"."+mrxpBase64url(new Uint8Array(sig));
}
async function mrxpVerifySnapshot(env,token){
 if(typeof token!=="string"||token.length>2500)return null;
 const parts=token.split(".");if(parts.length!==2)return null;
 try{
  const payload=parts[0],sig=mrxpUnbase64url(parts[1]);
  if(sig.byteLength!==32)return null;
  const verified=await crypto.subtle.verify("HMAC",await mrxpShareKey(env),sig,new TextEncoder().encode(payload));
  if(!verified)return null;
  const s=JSON.parse(new TextDecoder().decode(mrxpUnbase64url(payload)));
  if(s.v!==1||!Number.isInteger(s.issued_ms)||Date.now()-s.issued_ms<0||Date.now()-s.issued_ms>MRXP_SHARE_TTL_MS)return null;
  if(!Number.isInteger(s.level)||s.level<1||s.level>50||!Number.isInteger(s.avatar_rank)||s.avatar_rank<1||s.avatar_rank>11||s.avatar_rank>v2CurrentRankIndex(s.level)+1)return null;
  if(!Number.isSafeInteger(s.xp)||s.xp<0||!Number.isSafeInteger(s.missions)||s.missions<0)return null;
  if(typeof s.display_name!=="string"||s.display_name.length>42||typeof s.rank!=="string"||s.rank!==v2Rank(s.level).name)return null;
  return s;
 }catch{return null}
}
function mrxpEscapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
async function mrxpShareSnapshot(env,player,hideName){
 const progression=await v2Progression(env,player);
 const profile=await v2PlayerProfile(env,player,progression);
 const count=await env.DB.prepare("SELECT COUNT(*) AS total FROM mission_claims WHERE user_id=?").bind(player.user_id).first();
 const issued_ms=Date.now();
 const snapshot={v:1,issued_ms,display_name:hideName?"Joueur MRXP":mrxpSafeName(player.display_name),
  rank:progression.rank,level:progression.level,xp:progression.confirmed_xp,
  missions:Math.max(0,Number(count?.total||0)),mastery:progression.mastery.completed,
  progress_percent:progression.xp_progress_percent,avatar_rank:profile.selected_rank_id};
 return {snapshot,token:await mrxpShareToken(env,snapshot)};
}


/* V2 Phase 4 — Free MRXP virtual credit economy. No real currency.
   Only rows in verified server ledgers can generate credit events.
   Exactly-once credits: (user_id,event_key) is unique in SQLite D1.
   XP and credit balances never share a column or accounting formula. */
const MRXP_CREDIT_RANK_BONUSES={5:40,10:50,15:70,20:90,30:110,40:140,50:180};
const MRXP_CREDIT_POLICY={daily_base:5,daily_quest:5,wheel_quest:5,tap_quest:5,mission:10,weekly:30,ordinary_level:10};

/* Phase 6: all mutable economy controls are allowlisted integers from D1.
   They only alter future verified rewards, store prices and new purchases.
   Purchased SKUs retain their immutable XP/energy effect. */
const MRXP_BALANCE_FIELDS={
 shop_enabled:{label:"Boutique activée (0/1)",min:0,max:1,default:1,group:"release"},
 shop_rollout:{label:"Pourcentage du déploiement (0-100)",min:0,max:100,default:100,group:"release"},
 shop_daily_limit:{label:"Achats maximum par compte et par jour",min:1,max:100,default:30,group:"release"},
 "price_tap-110":{label:"Prix Boost Découverte",min:1,max:10000,default:25,group:"price"},
 "price_tap-120":{label:"Prix Boost Guerrier",min:1,max:10000,default:45,group:"price"},
 "price_tap-150":{label:"Prix Boost Champion",min:1,max:10000,default:100,group:"price"},
 "price_tap-200":{label:"Prix Boost Souverain",min:1,max:10000,default:180,group:"price"},
 "price_energy-100":{label:"Prix Recharge 100",min:1,max:10000,default:20,group:"price"},
 "price_energy-250":{label:"Prix Recharge 250",min:1,max:10000,default:45,group:"price"},
 reward_daily_base:{label:"Crédits par bonus quotidien",min:1,max:500,default:5,group:"reward"},
 reward_daily_quest:{label:"Crédits défi quotidien",min:1,max:500,default:5,group:"reward"},
 reward_wheel_quest:{label:"Crédits défi roue",min:1,max:500,default:5,group:"reward"},
 reward_tap_quest:{label:"Crédits défi 50 tapotages",min:1,max:500,default:5,group:"reward"},
 reward_mission:{label:"Crédits par mission permanente",min:1,max:500,default:10,group:"reward"},
 reward_weekly:{label:"Crédits semaine active",min:1,max:2000,default:30,group:"reward"},
 reward_ordinary_level:{label:"Crédits niveau ordinaire",min:1,max:500,default:10,group:"reward"},
 reward_rank_scale:{label:"Bonus de rang (% du barème)",min:10,max:300,default:100,group:"reward"}
};
async function mrxpBalanceConfig(env){
 const [r,audit]=await Promise.all([
  env.DB.prepare("SELECT key,value,updated_ms FROM bot_settings WHERE key LIKE 'mrxp_balance_%'").all(),
  env.DB.prepare("SELECT setting_key,old_value,new_value,created_ms FROM mrxp_balance_audit WHERE setting_key LIKE 'mrxp_balance_reward_%' ORDER BY created_ms ASC,rowid ASC").all()
 ]);
 const values={},updated={},history={};
 for(const [field,rule] of Object.entries(MRXP_BALANCE_FIELDS)){values[field]=rule.default;updated[field]=0}
 for(const row of r.results||[]){
  const field=String(row.key||"").replace(/^mrxp_balance_/,""),rule=MRXP_BALANCE_FIELDS[field];
  if(!rule||!/^\d+$/.test(String(row.value)))continue;
  const n=Number(row.value);
  if(!Number.isSafeInteger(n)||n<rule.min||n>rule.max)continue;
  values[field]=n;updated[field]=Number(row.updated_ms)||0
 }
 for(const row of audit.results||[]){
  const field=String(row.setting_key||"").replace(/^mrxp_balance_/,""),rule=MRXP_BALANCE_FIELDS[field];
  const previous=Number(row.old_value),next=Number(row.new_value),at=Number(row.created_ms);
  if(!rule||rule.group!=="reward"||!Number.isSafeInteger(previous)||!Number.isSafeInteger(next)||previous<rule.min||previous>rule.max||next<rule.min||next>rule.max||!Number.isFinite(at)||at<=0)continue;
  (history[field]??=[]).push({old:previous,value:next,at})
 }
 return {values,updated,history}
}
function mrxpBalancePrice(config,sku,fallback){
 return config?.values?.["price_"+sku]??fallback
}
function mrxpBalanceRate(config,field,eventMs){
 const setting="reward_"+field,base=MRXP_BALANCE_FIELDS[setting];
 if(!base)return 0;
 const entries=config?.history?.[setting]||[];
 if(entries.length){
  let value=entries[0].old;
  for(const entry of entries){if(eventMs<entry.at)break;value=entry.value}
  return value
 }
 const effective=Number(config?.updated?.[setting]||0);
 if(effective>0&&eventMs<effective)return base.default;
 return config?.values?.[setting]??base.default
}
function mrxpBalanceRankReward(config,amount){
 return Math.floor(amount*(config?.values?.reward_rank_scale??100)/100)
}
function mrxpBalanceCatalog(config){
 return MRXP_BOOST_CATALOG.map(item=>({...item,price:mrxpBalancePrice(config,item.sku,item.price)}))
}
function mrxpBalanceRolloutBucket(userId){
 let hash=2166136261;for(const c of String(userId)){hash=Math.imul(hash^c.charCodeAt(0),16777619)>>>0}
 return hash%100
}
function mrxpBalanceCanBuy(config,userId){
 if(config.values.shop_enabled!==1)return false;
 return mrxpBalanceRolloutBucket(userId)<config.values.shop_rollout
}
async function mrxpBalanceChange(env,adminId,field,newValue){
 const rule=MRXP_BALANCE_FIELDS[field];
 if(!rule||typeof newValue!=="number"||!Number.isSafeInteger(newValue)||newValue<rule.min||newValue>rule.max)throw Error("Paramètre interdit ou hors limites");
 if(!await isBotAdmin(env,adminId))throw Error("Accès administrateur refusé");
 const key="mrxp_balance_"+field,now=Date.now();
 const previous=await env.DB.prepare("SELECT value FROM bot_settings WHERE key=?").bind(key).first();
 const old=previous?.value??String(rule.default);
 if(old===String(newValue))return {changed:false,old,current:newValue};
 await env.DB.batch([
  env.DB.prepare("INSERT INTO mrxp_balance_audit(admin_id,setting_key,old_value,new_value,created_ms) VALUES(?,?,?,?,?)").bind(String(adminId),key,old,String(newValue),now),
  env.DB.prepare("INSERT INTO bot_settings(key,value,updated_ms) VALUES(?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_ms=excluded.updated_ms").bind(key,String(newValue),now)
 ]);
 return {changed:true,old,current:newValue}
}

function mrxpWeekMonday(day){
 const d=new Date(day+"T00:00:00Z"),offset=(d.getUTCDay()+6)%7;
 return new Date(d.getTime()-offset*86400000).toISOString().slice(0,10)
}
async function mrxpCreditBaseline(env,player,progression){
 const id=String(player.user_id);
 let baseline=await env.DB.prepare("SELECT baseline_level,activated_ms FROM player_credit_state WHERE user_id=?").bind(id).first();
 if(!baseline){
  const p=progression||await v2Progression(env,player);
  await env.DB.prepare("INSERT OR IGNORE INTO player_credit_state(user_id,baseline_level,activated_ms) VALUES(?,?,?)").bind(id,p.level,Date.now()).run();
  baseline=await env.DB.prepare("SELECT baseline_level,activated_ms FROM player_credit_state WHERE user_id=?").bind(id).first()
 }
 if(!baseline)throw Error("MRXP credit baseline missing");
 return {baseline_level:Math.max(1,Math.min(50,Number(baseline.baseline_level)||1)),
  activated_ms:Math.max(1,Number(baseline.activated_ms)||Date.now())}
}
async function mrxpWallet(env,player,progression){
 const id=String(player.user_id),p=progression||await v2Progression(env,player);
 const [state,config]=await Promise.all([mrxpCreditBaseline(env,player,p),mrxpBalanceConfig(env)]);
 const existing=await env.DB.prepare("SELECT event_key FROM mrxp_credit_events WHERE user_id=?").bind(id).all();
 const owned=new Set((existing.results||[]).map(x=>x.event_key));
 const baselineDay=new Date(state.activated_ms).toISOString().slice(0,10),entries=[];
 const add=(key,type,amount,label,ms)=>{
  if(owned.has(key)||!Number.isSafeInteger(amount)||amount<=0)return;
  owned.add(key);entries.push({key,type,amount,label,ms})
 };
 const [d,w,t,m]=await Promise.all([
  env.DB.prepare("SELECT day,created_ms FROM daily_claims WHERE user_id=? AND created_ms>=? ORDER BY day").bind(id,state.activated_ms).all(),
  env.DB.prepare("SELECT day,created_ms FROM wheel_claims WHERE user_id=? AND created_ms>=? ORDER BY day").bind(id,state.activated_ms).all(),
  env.DB.prepare("SELECT created_ms,taps FROM sync_receipts WHERE user_id=? AND created_ms>=? AND taps>0 ORDER BY created_ms").bind(id,state.activated_ms).all(),
  env.DB.prepare("SELECT mission_key,created_ms FROM mission_claims WHERE user_id=? AND created_ms>=? ORDER BY created_ms").bind(id,state.activated_ms).all()
 ]);
 const dailyWeeks=new Map(),dailyWeekTimes=new Map();
 for(const row of d.results||[]){
  const day=String(row.day||"");if(!/^\d{4}-\d{2}-\d{2}$/.test(day)||day<baselineDay)continue;
  const week=mrxpWeekMonday(day);if(!dailyWeeks.has(week))dailyWeeks.set(week,new Set());
  dailyWeeks.get(week).add(day);
  if(!dailyWeekTimes.has(week))dailyWeekTimes.set(week,new Map());
  dailyWeekTimes.get(week).set(day,Number(row.created_ms));
  add("daily:"+day,"daily",mrxpBalanceRate(config,"daily_base",Number(row.created_ms)),"Bonus quotidien validé",Number(row.created_ms));
  add("quest:daily:"+day,"quest",mrxpBalanceRate(config,"daily_quest",Number(row.created_ms)),"Défi : bonus quotidien confirmé",Number(row.created_ms))
 }
 for(const row of w.results||[]){
  const day=String(row.day||"");if(!/^\d{4}-\d{2}-\d{2}$/.test(day)||day<baselineDay)continue;
  add("quest:wheel:"+day,"quest",mrxpBalanceRate(config,"wheel_quest",Number(row.created_ms)),"Défi : Lucky Wheel confirmée",Number(row.created_ms))
 }
 const tapDays=new Map();
 for(const row of t.results||[]){
  const ms=Number(row.created_ms),taps=Number(row.taps);
  if(!Number.isFinite(ms)||ms<=0||!Number.isSafeInteger(taps)||taps<=0)continue;
  const day=new Date(ms).toISOString().slice(0,10),previous=tapDays.get(day)||{count:0,achieved_ms:0};
  previous.count+=taps;
  if(previous.count>=50&&!previous.achieved_ms)previous.achieved_ms=ms;
  tapDays.set(day,previous)
 }
 for(const [day,total] of tapDays){
  if(total.count<50)continue;
  const ms=total.achieved_ms;
  add("quest:taps:"+day,"quest",mrxpBalanceRate(config,"tap_quest",ms),"Défi : 50 tapotages cumulés et synchronisés",ms)
 }
 for(const row of m.results||[]){
  const key=String(row.mission_key||"");if(!/^[a-z][a-z0-9_]{0,79}$/.test(key))continue;
  add("mission:"+key,"mission",mrxpBalanceRate(config,"mission",Number(row.created_ms)),"Mission validée : "+key,Number(row.created_ms))
 }
 for(const [week,days] of dailyWeeks){
  if(days.size>=4){const sorted=[...days].sort(),fourth=dailyWeekTimes.get(week)?.get(sorted[3])||Date.parse(sorted[3]+"T23:59:59.000Z");add("weekly:"+week,"weekly",mrxpBalanceRate(config,"weekly",fourth),"Semaine active : 4 bonus quotidiens",fourth)}
 }
 for(let n=state.baseline_level+1;n<=p.level;n++){
  const rankName=V2_RANKS.find(r=>r.from===n)?.name;
  const amount=MRXP_CREDIT_RANK_BONUSES[n]?mrxpBalanceRankReward(config,MRXP_CREDIT_RANK_BONUSES[n]):mrxpBalanceRate(config,"ordinary_level",Date.now());
  add("level:"+n,rankName?"rank":"level",amount,rankName?"Nouveau rang : "+rankName:"Niveau "+n+" atteint",Date.now())
 }
 for(let n=0;n<entries.length;n+=50){
  const group=entries.slice(n,n+50).map(e=>env.DB.prepare("INSERT OR IGNORE INTO mrxp_credit_events(user_id,event_key,event_type,amount,label,created_ms) VALUES(?,?,?,?,?,?)").bind(id,e.key,e.type,e.amount,e.label,Number.isFinite(e.ms)&&e.ms>0?e.ms:Date.now()));
  await env.DB.batch(group)
 }
 const [balance,history]=await Promise.all([
  env.DB.prepare("SELECT COALESCE(SUM(amount),0) AS balance, COUNT(*) AS event_count FROM mrxp_credit_events WHERE user_id=?").bind(id).first(),
  env.DB.prepare("SELECT event_key,event_type,amount,label,created_ms FROM mrxp_credit_events WHERE user_id=? ORDER BY created_ms DESC,event_key DESC LIMIT 50").bind(id).all()
 ]);
 return {currency:"MRXP",balance:Math.max(0,Number(balance?.balance)||0),total_events:Number(balance?.event_count)||0,
  ledger:(history.results||[]).map(x=>({key:x.event_key,type:x.event_type,amount:Number(x.amount),label:x.label,created_ms:Number(x.created_ms)})),
  spend_enabled:mrxpBalanceCanBuy(config,id),transfer_enabled:false,cash_value:false,
  today_goals:(()=>{const day=new Date().toISOString().slice(0,10);
   return [
    {key:"daily",label:"Bonus quotidien synchronisé",done:(d.results||[]).some(r=>r.day===day),reward:mrxpBalanceRate(config,"daily_quest",Date.now())},
    {key:"wheel",label:"Roue du jour confirmée",done:(w.results||[]).some(r=>r.day===day),reward:mrxpBalanceRate(config,"wheel_quest",Date.now())},
    {key:"taps",label:"50 tapotages synchronisés",done:(tapDays.get(day)?.count||0)>=50,reward:mrxpBalanceRate(config,"tap_quest",Date.now())}
   ]
  })(),
  weekly:{done:(dailyWeeks.get(mrxpWeekMonday(new Date().toISOString().slice(0,10)))?.size||0)>=4,
    days:dailyWeeks.get(mrxpWeekMonday(new Date().toISOString().slice(0,10)))?.size||0,
    target:4,reward:mrxpBalanceRate(config,"weekly",Date.now())},
  policy:Object.fromEntries(Object.keys(MRXP_CREDIT_POLICY).map(key=>[key,mrxpBalanceRate(config,key,Date.now())])),baseline_level:state.baseline_level,activated_ms:state.activated_ms}
}


/* V2 Phase 5 — shop and boost accounting. All prices/effects are server-owned.
   No client-supplied price or multiplier can influence XP or credit balance.
   Activation of tap boosts is queued for the next admissible 12h sync; the
   clock begins on that first successful sync so every purchase gets use. */
const MRXP_BOOST_CATALOG=[
 {sku:"tap-110",label:"Boost Découverte",icon:"⚡",kind:"tap",price:25,multiplier_milli:1100,duration_hours:24,description:"x1,1 XP sur les tapotages confirmés"},
 {sku:"tap-120",label:"Boost Guerrier",icon:"🔥",kind:"tap",price:45,multiplier_milli:1200,duration_hours:24,description:"x1,2 XP sur les tapotages confirmés"},
 {sku:"tap-150",label:"Boost Champion",icon:"👑",kind:"tap",price:100,multiplier_milli:1500,duration_hours:24,description:"x1,5 XP sur les tapotages confirmés"},
 {sku:"tap-200",label:"Boost Souverain",icon:"💎",kind:"tap",price:180,multiplier_milli:2000,duration_hours:24,description:"x2 XP sur les tapotages confirmés"},
 {sku:"energy-100",label:"Recharge 100",icon:"🔋",kind:"energy",price:20,energy:100,duration_hours:72,description:"+100 énergie (maximum 500)"},
 {sku:"energy-250",label:"Recharge 250",icon:"🔌",kind:"energy",price:45,energy:250,duration_hours:72,description:"+250 énergie (maximum 500)"}
];
function mrxpBoostSku(sku){return MRXP_BOOST_CATALOG.find(x=>x.sku===sku)||null}

/* Limit request memory and reject excessively large client-supplied actions. */
async function mrxpParseAction(request,maxBytes=16384){
 const len=request.headers.get("content-length");
 if(len!==null&&(!/^\d+$/.test(len)||Number(len)>maxBytes))throw Error("REQUEST_TOO_LARGE");
 if(!request.body)throw Error("JSON_INVALIDE");
 const reader=request.body.getReader(),parts=[];
 let size=0;
 try{
  for(;;){
   const {value,done}=await reader.read();if(done)break;
   if(!value)continue;
   size+=value.byteLength;
   if(size>maxBytes){try{await reader.cancel()}catch{}throw Error("REQUEST_TOO_LARGE")}
   parts.push(value)
  }
 }finally{reader.releaseLock()}
 const bytes=new Uint8Array(size);let offset=0;
 for(const part of parts){bytes.set(part,offset);offset+=part.byteLength}
 return JSON.parse(new TextDecoder("utf-8",{fatal:true}).decode(bytes))
}

const MRXP_BOOST_PURCHASE_PATTERN=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
async function mrxpBoostExpire(env,id){
 return env.DB.prepare("UPDATE mrxp_boost_inventory SET state='expired' WHERE user_id=? AND state IN ('active','charged') AND expires_ms>0 AND expires_ms<=?").bind(String(id),Date.now()).run()
}
async function mrxpBoostList(env,player,wallet){
 const id=String(player.user_id);
 const config=await mrxpBalanceConfig(env);
 await mrxpBoostExpire(env,id);
 const r=await env.DB.prepare("SELECT purchase_id,sku,kind,cost,state,bought_ms,activated_ms,expires_ms FROM mrxp_boost_inventory WHERE user_id=? ORDER BY bought_ms DESC LIMIT 100").bind(id).all();
 const inventory=(r.results||[]).map(b=>({
  id:String(b.purchase_id),sku:String(b.sku),kind:String(b.kind),
  price:Number(b.cost),state:String(b.state),bought_ms:Number(b.bought_ms),
  activated_ms:Number(b.activated_ms),expires_ms:Number(b.expires_ms),
  item:mrxpBoostSku(String(b.sku))
 }));
 const activeTap=inventory.find(x=>x.kind==="tap"&&(x.state==="queued"||x.state==="active"))||null;
 const energyCharged=inventory.find(x=>x.kind==="energy"&&x.state==="charged")||null;
 return {catalog:mrxpBalanceCatalog(config),available:mrxpBalanceCanBuy(config,id),rollout_percent:config.values.shop_rollout,inventory,
  active_tap:activeTap,energy_charged:energyCharged,
  balance:wallet?wallet.balance:null,server_time:Date.now(),
  sync_hours:12,stacking:false,real_money:false,
  note:"Un seul multiplicateur XP à la fois. Activation lors de la prochaine synchronisation autorisée; valable 24 h après son premier effet. Les recharges d'énergie sont utilisables immédiatement et validées au prochain envoi de tapotages."}
}
async function mrxpPurchaseBoost(env,player,payload){
 const id=String(player.user_id);
 const sku=String(payload?.sku||""),purchaseId=String(payload?.purchase_id||"");
 const config=await mrxpBalanceConfig(env);
 const itemBase=mrxpBoostSku(sku),item=itemBase?{...itemBase,price:mrxpBalancePrice(config,sku,itemBase.price)}:null;
 if(!item)return {status:400,error:"BOOST_UNKNOWN"};
 if(!MRXP_BOOST_PURCHASE_PATTERN.test(purchaseId))return {status:400,error:"PURCHASE_ID_INVALID"};
 const wallet=await mrxpWallet(env,player);
 const existing=await env.DB.prepare("SELECT purchase_id,sku,cost FROM mrxp_boost_inventory WHERE user_id=? AND purchase_id=?").bind(id,purchaseId).first();
 if(existing)return existing.sku===sku?{ok:true,duplicate:true,wallet,shop:await mrxpBoostList(env,player,wallet)}:{status:409,error:"PURCHASE_ID_REUSED"};
 if(!mrxpBalanceCanBuy(config,id))return {status:423,error:"SHOP_NOT_AVAILABLE"};
 if(wallet.balance<item.price)return {status:409,error:"INSUFFICIENT_CREDITS",balance:wallet.balance};
 const now=Date.now(),dayStart=Math.floor(now/86400000)*86400000,limit=config.values.shop_daily_limit;
 const purchases=await env.DB.prepare("SELECT COUNT(*) AS n FROM mrxp_boost_inventory WHERE user_id=? AND bought_ms>=?").bind(id,dayStart).first();
 if(Number(purchases?.n||0)>=limit)return {status:429,error:"SHOP_DAILY_LIMIT"};
 /* D1 batch runs as one transaction; the debit INSERT is required and can
    happen only if the immediately previous inventory INSERT changed a row. */
 const rows=await env.DB.batch([
  env.DB.prepare("INSERT OR IGNORE INTO mrxp_boost_inventory(user_id,purchase_id,sku,kind,cost,state,bought_ms,activated_ms,expires_ms,carry_milli) SELECT ?,?,?,?,?, 'owned',?,0,0,0 WHERE (SELECT COALESCE(SUM(amount),0) FROM mrxp_credit_events WHERE user_id=?)>=? AND (SELECT COUNT(*) FROM mrxp_boost_inventory WHERE user_id=? AND bought_ms>=?)<? AND NOT EXISTS(SELECT 1 FROM mrxp_boost_inventory WHERE user_id=? AND purchase_id=?)").bind(id,purchaseId,item.sku,item.kind,item.price,now,id,item.price,id,dayStart,limit,id,purchaseId),
  env.DB.prepare("INSERT INTO mrxp_credit_events(user_id,event_key,event_type,amount,label,created_ms) SELECT ?,?,'purchase',?,?,? WHERE changes()=1").bind(id,"buy:"+purchaseId,-item.price,"Boutique : "+item.label,now)
 ]);
 const accepted=Number(rows[0]?.meta?.changes||0)===1;
 if(!accepted){
  const retry=await env.DB.prepare("SELECT sku FROM mrxp_boost_inventory WHERE user_id=? AND purchase_id=?").bind(id,purchaseId).first();
  if(!retry){const count=await env.DB.prepare("SELECT COUNT(*) AS n FROM mrxp_boost_inventory WHERE user_id=? AND bought_ms>=?").bind(id,dayStart).first();return Number(count?.n||0)>=limit?{status:429,error:"SHOP_DAILY_LIMIT"}:{status:409,error:"INSUFFICIENT_CREDITS"}};
  if(retry.sku!==sku)return {status:409,error:"PURCHASE_ID_REUSED"}
 }
 const fresh=await mrxpWallet(env,player);
 return {ok:true,duplicate:!accepted,wallet:fresh,shop:await mrxpBoostList(env,player,fresh)}
}
async function mrxpActivateBoost(env,player,payload){
 const id=String(player.user_id),purchaseId=String(payload?.purchase_id||"");
 if(!MRXP_BOOST_PURCHASE_PATTERN.test(purchaseId))return {status:400,error:"PURCHASE_ID_INVALID"};
 await mrxpBoostExpire(env,id);
 const row=await env.DB.prepare("SELECT purchase_id,sku,kind,state,expires_ms FROM mrxp_boost_inventory WHERE user_id=? AND purchase_id=?").bind(id,purchaseId).first();
 if(!row)return {status:404,error:"BOOST_NOT_OWNED"};
 const item=mrxpBoostSku(String(row.sku));
 if(!item)return {status:409,error:"BOOST_UNAVAILABLE"};
 if(row.state!=="owned"){
  if(["queued","active","charged","used"].includes(row.state))return {ok:true,duplicate:true,applied_energy:row.state==="charged"&&item.kind==="energy"?item.energy:0,purchase_id:purchaseId,shop:await mrxpBoostList(env,player)};
  return {status:409,error:"BOOST_EXPIRED"};
 }
 const now=Date.now(),tap=item.kind==="tap";
 const existing=await env.DB.prepare("SELECT purchase_id FROM mrxp_boost_inventory WHERE user_id=? AND kind=? AND state IN (?,?) LIMIT 1").bind(id,item.kind,tap?"queued":"charged",tap?"active":"charged").first();
 if(existing&&existing.purchase_id!==purchaseId)return {status:409,error:tap?"BOOST_ALREADY_ACTIVE":"ENERGY_ALREADY_CHARGED"};
 const result=await env.DB.prepare(tap?
  "UPDATE mrxp_boost_inventory SET state='queued' WHERE user_id=? AND purchase_id=? AND state='owned' AND NOT EXISTS(SELECT 1 FROM mrxp_boost_inventory WHERE user_id=? AND kind='tap' AND state IN ('queued','active') AND purchase_id<>?)":
  "UPDATE mrxp_boost_inventory SET state='charged',activated_ms=?,expires_ms=? WHERE user_id=? AND purchase_id=? AND state='owned' AND NOT EXISTS(SELECT 1 FROM mrxp_boost_inventory WHERE user_id=? AND kind='energy' AND state='charged' AND purchase_id<>?)"
 ).bind(...(tap?[id,purchaseId,id,purchaseId]:[now,now+item.duration_hours*3600000,id,purchaseId,id,purchaseId])).run();
 if(Number(result?.meta?.changes||0)!==1)return {status:409,error:"BOOST_ACTIVATION_CONFLICT"};
 return {ok:true,duplicate:false,applied_energy:tap?0:item.energy,purchase_id:purchaseId,shop:await mrxpBoostList(env,player)}
}
async function mrxpBoostSyncContext(env,player,now){
 const id=String(player.user_id);
 await mrxpBoostExpire(env,id);
 const [t,e]=await Promise.all([
  env.DB.prepare("SELECT purchase_id,sku,state,expires_ms,carry_milli FROM mrxp_boost_inventory WHERE user_id=? AND kind='tap' AND (state='queued' OR (state='active' AND expires_ms>?)) ORDER BY bought_ms DESC LIMIT 1").bind(id,now).first(),
  env.DB.prepare("SELECT purchase_id,sku FROM mrxp_boost_inventory WHERE user_id=? AND kind='energy' AND state='charged' AND expires_ms>? ORDER BY bought_ms DESC LIMIT 1").bind(id,now).first()
 ]);
 const multiplier=t?mrxpBoostSku(t.sku):null,energy=e?mrxpBoostSku(e.sku):null;
 return {tap:multiplier?.kind==="tap"?t:null,tapItem:multiplier?.kind==="tap"?multiplier:null,
  energy:energy?.kind==="energy"?e:null,energyItem:energy?.kind==="energy"?energy:null}
}

